function test_pricingBoundsChangesBetweenBeforeAndAfterSwap() public {
    // Setup: Set wide pricing bounds, enable direct swap
    vm.prank(tokenAdmin);
    registry.setPricingBounds(token, pairTokens, [uint160(100)], [uint160(1e36)], hooks);

    // Action: beforeSwap stores amount, returns early (no bound check)
    vm.prank(address(amm));
    hook.beforeSwap(context, directSwapParams, bytes(''));

    // Between before/after: admin tightens bounds via registry
    vm.prank(tokenAdmin);
    registry.setPricingBounds(token, pairTokens, [uint160(1e30)], [uint160(1e30 + 1)], hooks);

    // afterSwap now uses tightened bounds
    vm.prank(address(amm));
    vm.expectRevert(AMMStandardHook.AMMStandardHook__InvalidPrice.selector);
    hook.afterSwap(context, directSwapParams, bytes(''));
    // Swap fails at afterSwap despite being valid at beforeSwap time
}
